package com.littlered.pocketaistudio\n\nimport android.app.Activity\nimport android.os.Bundle\nimport android.speech.tts.TextToSpeech\nimport android.view.Gravity\nimport android.widget.*\nimport dev.ffmpegkit.llama.Llama\nimport dev.ffmpegkit.llama.LlamaConfig\nimport dev.ffmpegkit.llama.LlamaModel\nimport kotlinx.coroutines.*\nimport java.io.File\nimport java.net.HttpURLConnection\nimport java.net.URL\nimport java.util.Locale\n\nclass MainActivity : Activity() {\n private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)\n private lateinit var status: TextView\n private lateinit var chat: TextView\n private lateinit var input: EditText\n private lateinit var send: Button\n private lateinit var download: Button\n private lateinit var voice: CheckBox\n private var model: LlamaModel? = null\n private var tts: TextToSpeech? = null\n private val modelUrl = "https://huggingface.co/Qwen/Qwen2.5-0.5B-Instruct-GGUF/resolve/main/qwen2.5-0.5b-instruct-q2_k.gguf"\n private val modelName = "qwen2.5-0.5b-instruct-q2_k.gguf"\n\n override fun onCreate(b: Bundle?) { super.onCreate(b); tts=TextToSpeech(this){ if(it==TextToSpeech.SUCCESS) tts?.language=Locale.US }; buildUi(); refresh() }\n\n private fun buildUi() {\n  val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(24,24,24,16);setBackgroundColor(0xFF0D1117.toInt())}\n  root.addView(TextView(this).apply{text="RED'S AI POCKET";textSize=26f;setTextColor(0xFFFFFFFF.toInt());gravity=Gravity.CENTER},LinearLayout.LayoutParams(-1,58))\n  root.addView(TextView(this).apply{text="YOUR AI • ONLINE DOWNLOAD • OFFLINE CHAT";textSize=13f;setTextColor(0xFFB8C1CC.toInt());gravity=Gravity.CENTER},LinearLayout.LayoutParams(-1,42))\n  status=TextView(this).apply{textSize=14f;setTextColor(0xFF9FE870.toInt());gravity=Gravity.CENTER};root.addView(status,LinearLayout.LayoutParams(-1,42))\n  download=Button(this).apply{text="DOWNLOAD STARTER AI • ~339 MB";setOnClickListener{downloadModel()}};root.addView(download,LinearLayout.LayoutParams(-1,54))\n  val scroll=ScrollView(this);chat=TextView(this).apply{textSize=16f;setTextColor(0xFFE8EDF3.toInt());setPadding(8,16,8,16);text="This is a real on-device AI app, not a web wrapper.\\n\\nDownload the starter model once while online. After that, it runs locally without internet."};scroll.addView(chat);root.addView(scroll,LinearLayout.LayoutParams(-1,0,1f))\n  input=EditText(this).apply{hint="Ask your AI...";setTextColor(0xFFFFFFFF.toInt());setHintTextColor(0xFF77818D.toInt());setMinLines(2);setMaxLines(4)};root.addView(input,LinearLayout.LayoutParams(-1,76))\n  val row=LinearLayout(this);send=Button(this).apply{text="ASK";isEnabled=false;setOnClickListener{ask()}};row.addView(send,LinearLayout.LayoutParams(0,54,1f));voice=CheckBox(this).apply{text="VOICE";setTextColor(0xFFFFFFFF.toInt());isChecked=true};row.addView(voice,LinearLayout.LayoutParams(0,54,1f));root.addView(row);setContentView(root)\n }\n\n private fun file(): File = File(File(getExternalFilesDir(null),"models").apply{mkdirs()},modelName)\n private fun refresh(){val f=file();if(f.exists()&&f.length()>100_000_000L){status.text="MODEL FOUND • LOADING LOCAL AI";download.text="MODEL INSTALLED • OFFLINE READY";scope.launch{load(f)}}else status.text="ONLINE READY • DOWNLOAD MODEL TO START"}\n\n private fun downloadModel(){download.isEnabled=false;status.text="DOWNLOADING MODEL…";scope.launch(Dispatchers.IO){try{val target=file();val temp=File(target.parentFile,"$modelName.part");val c=(URL(modelUrl).openConnection() as HttpURLConnection).apply{connectTimeout=20000;readTimeout=60000};c.connect();if(c.responseCode !in 200..299)error("HTTP ${c.responseCode}");val total=c.contentLengthLong;var done=0L;c.inputStream.use{ins->temp.outputStream().use{out->val buf=ByteArray(65536);while(true){val n=ins.read(buf);if(n<0)break;out.write(buf,0,n);done+=n;if(total>0)withContext(Dispatchers.Main){status.text="DOWNLOADING MODEL… ${(done*100/total).toInt()}%"}}}};if(temp.length()<100_000_000L)error("Incomplete model download");if(target.exists())target.delete();if(!temp.renameTo(target))error("Could not save model");withContext(Dispatchers.Main){status.text="MODEL DOWNLOADED • LOADING"};load(target)}catch(e:Exception){withContext(Dispatchers.Main){status.text="DOWNLOAD FAILED • ${e.message?:"unknown error"}";download.isEnabled=true}}}}\n\n private suspend fun load(f:File){try{val m=withContext(Dispatchers.Default){Llama.loadModel(f.absolutePath,LlamaConfig(contextSize=2048,threads=4))};model?.let{Llama.releaseModel(it)};model=m;withContext(Dispatchers.Main){status.text="OFFLINE AI READY • LLAMA.CPP";send.isEnabled=true;download.isEnabled=false}}catch(e:Exception){withContext(Dispatchers.Main){status.text="MODEL LOAD FAILED • ${e.message?:"unsupported model"}";download.isEnabled=true}}}\n\n private fun ask(){val p=input.text.toString().trim();val m=model?:return;if(p.isEmpty())return;input.setText("");send.isEnabled=false;chat.append("\\n\\nYOU: $p");scope.launch{try{val r=Llama.complete(m,prompt=p,systemPrompt="You are Red's private pocket AI. Be helpful, concise, warm and honest. You run locally on the user's phone.",maxTokens=256);val a=r.text.trim();chat.append("\\n\\nAI: $a");if(voice.isChecked)tts?.speak(a,TextToSpeech.QUEUE_FLUSH,null,"red-ai")}catch(e:Exception){chat.append("\\n\\nAI ERROR: ${e.message?:"inference failed"}")}finally{send.isEnabled=true}}}\n\n override fun onDestroy(){scope.cancel();model?.let{Llama.releaseModel(it)};tts?.stop();tts?.shutdown();super.onDestroy()}\n}